```
import java.util.Arrays;
public class ExtinctMammals {
   public static void main(String[] args) {
      String[] mammals = {"Baiji Dolphin", "Thylacine", "Pyrenean Ibex", "Eastern Cougar", "Vietnamese Javan Rhino"};
      int[] extinctionYear = {2006, 1936, 2000, 2018, 2011};
      String[] conservationStatus = {"Critically Endangered", "Extinct", "Extinct", "Endangered", "Critically Endangered"};
      int[] birthYear = {1990, 1880, 1995, 2010, 1985};
      int[] lifespan = new int[5];
      for(int i=0; i<5; i++){
        lifespan[i] = extinctionYear[i] - birthYear[i];
      }
      String[][] data = new String[5][4];
      for(int i=0; i<5; i++){
        data[i][0] = mammals[i];
        data[i][1] = Integer.toString(extinctionYear[i]);
        data[i][2] = conservationStatus[i];
        data[i][3] = Integer.toString(lifespan[i]);
      }
      Arrays.sort(data, (a, b) -> a[0].compareTo(b[0]));
      System.out.println("Names of the five most recently extinct mammals in alphabetical order, along with their extinction year, conservation status, and average lifespan:");
      for(int i=0; i<5; i++){
        System.out.println(data[i][0] + " (" + data[i][1] + ") - " + data[i][2] + " - Average lifespan: " + data[i][3] + " years");
      }
   }
}
```
