// Payment gateway integration
import java.net.URL
import java.net.URLEncoder
import scala.io.Source
object PaymentGateway {
  def processPayment(amount: Double, creditCardNumber: String, expiryMonth: Int, expiryYear: Int): Boolean = {
    val url = "https://example.com/process_payment"
    val params = Map(
      "amount" -> amount.toString,
      "creditCardNumber" -> creditCardNumber,
      "expiryMonth" -> expiryMonth.toString,
      "expiryYear" -> expiryYear.toString
    )
    val encodedParams = params.map(p => p._1 + "=" + URLEncoder.encode(p._2, "UTF-8")).mkString("&")
    val response = Source.fromURL(new URL(url + "?" + encodedParams)).mkString
    response == "success"
  }
}
