  return std::sqrt(std::pow(a.productivity_score - b.productivity_score, 2) + std::pow(a.communication_score - b.communication_score, 2));
}
std::vector<int> kmeans(const std::vector<TeamMember>& team_members, int k) {
  std::vector<int> cluster_assignments(team_members.size());
  std::vector<TeamMember> centroids(k);
  for (int i = 0; i < k; ++i) {
    centroids[i] = team_members[i];
  }
  bool converged = false;
  while (!converged) {
    std::vector<std::vector<TeamMember>> clusters(k);
    for (const auto& team_member : team_members) {
      double min_distance = std::numeric_limits<double>::max();
      int min_distance_index = -1;
      for (int i = 0; i < k; ++i) {
        double distance = euclidean_distance(team_member, centroids[i]);
        if (distance < min_distance) {
          min_distance = distance;
          min_distance_index = i;
        }
      }
      clusters[min_distance_index].push_back(team_member);
      cluster_assignments[&team_member - &team_members[0]] = min_distance_index;
    }
    converged = true;
    for (int i = 0; i < k; ++i) {
      TeamMember new_centroid {"", ' ', 0, 0};
      int cluster_size = clusters[i].size();
      for (const auto& team_member : clusters[i]) {
        new_centroid.productivity_score += team_member.productivity_score;
        new_centroid.communication_score += team_member.communication_score;
      }
      if (cluster_size > 0) {
        new_centroid.productivity_score /= cluster_size;
        new_centroid.communication_score /= cluster_size;
      }
      if (new_centroid.productivity_score != centroids[i].productivity_score || new_centroid.communication_score != centroids[i].communication_score) {
        centroids[i] = new_centroid;
        converged = false;
      }
    }
  }
  return cluster_assignments;
}
int main() {
  std::vector<TeamMember> team_members {
    {"John", 'A', 8, 7},
    {"Jane", 'B', 6, 9},
    {"Mike", 'A', 9, 6},
    {"Sarah", 'B', 5, 8}
  };
  std::vector<int> cluster_assignments = kmeans(team_members, 2);
  for (int i = 0; i < team_members.size(); ++i) {
    std::cout << team_members[i].name << " assigned to cluster " << cluster_assignments[i] << std::endl;
  }
  return 0;
}
```
This code defines a `euclidean_distance` function that calculates the Euclidean distance between two `TeamMember` objects, and a `kmeans` function that implements the k-means clustering algorithm. The `main` function creates a vector of `TeamMember` objects and calls the `kmeans` function to cluster the team members into two clusters. The `for` loop then prints out the cluster assignments for each team member.
In this example, the k-means clustering algorithm is used to group team members into two clusters based on their productivity and communication scores. The resulting cluster assignments can be used to identify potential conflicts between Type A and Type B individuals, and to develop strategies for improving workplace dynamics for Type B individuals.

Certainly! Here's a C++ program that reduces the fraction 4/10 to its lowest terms without using any built-in function or library for finding the greatest common divisor (GCD):
```
#include <iostream>
using namespace std;
int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}
int main() {
    int numerator = 4;
    int denominator = 10;
    int divisor = gcd(numerator, denominator);
    numerator /= divisor;
    denominator /= divisor;
    cout << numerator << "/" << denominator << endl;
    return 0;
}
```
The `gcd` function uses Euclid's algorithm to find the GCD of two integers. It works by repeatedly finding the remainder of dividing the larger number by the smaller number, and then swapping the numbers until the remainder is zero. The final divisor is the GCD.
Once we have the GCD, we divide both the numerator and denominator by it to get the reduced fraction. Finally, we print the result to the console.

