        }
        return data;
    }
    private static Instances[] splitDataset(Instances data, double splitRatio) {
        Random rand = new Random();
        Instances[] splitData = new Instances[2];
        splitData[0] = new Instances(data, 0);
        splitData[1] = new Instances(data, 0);
        for (int i = 0; i < data.numInstances(); i++) {
            Instances targetData = rand.nextDouble() < splitRatio ? splitData[0] : splitData[1];
            targetData.add(data.instance(i));
        }
        return splitData;
    }
    private static LinearRegression trainModel(Instances data) throws Exception {
        LinearRegression model = new LinearRegression();
        model.buildClassifier(data);
        return model;
    }
    private static Evaluation evaluateModel(LinearRegression model, Instances data) throws Exception {
        Evaluation eval = new Evaluation(data);
        eval.evaluateModel(model, data);
        return eval;
    }
    private static double[] makePredictions(LinearRegression model, Instances data) throws Exception {
        List<Double> predictions = new ArrayList<>();
        for (int i = 0; i < data.numInstances(); i++) {
            double prediction = model.classifyInstance(data.instance(i));
            predictions.add(prediction);
        }
        return predictions.stream().mapToDouble(Double::doubleValue).toArray();
    }
}
