import java.util.*;
public class UniqueWordGenerator {
  private static final String[] CONSONANTS = {"b", "c", "d", "f", "g", "h", "j", "k", "l", "m", "n", "p", "q", "r", "s", "t", "v", "w", "x", "y", "z"};
  private static final String[] VOWELS = {"a", "e", "i", "o", "u"};
  private static final Set<String> generatedWords = new HashSet<>();
  public static String generateWord() {
    String consonant = CONSONANTS[new Random().nextInt(CONSONANTS.length)];
    String vowel1 = VOWELS[new Random().nextInt(VOWELS.length)];
    String vowel2 = VOWELS[new Random().nextInt(VOWELS.length)];
    String vowel3 = VOWELS[new Random().nextInt(VOWELS.length)];
    String word = consonant + vowel1 + vowel2 + vowel3;
    while (generatedWords.contains(word.substring(1))) {
      consonant = CONSONANTS[new Random().nextInt(CONSONANTS.length)];
      word = consonant + vowel1 + vowel2 + vowel3;
    }
    generatedWords.add(word.substring(1));
    return word;
  }
}
