Sure, here's a Python function that takes a fruit name as input and outputs its corresponding price from a table stored in a separate file:
```
def fruit_price(fruit, currency='USD'):
    try:
        with open('fruit_prices.txt', 'r') as file:
            prices = {}
            for line in file:
                name, price = line.strip().split(' | ')
                prices[name.lower()] = float(price)
            if fruit.lower() in prices:
                price = prices[fruit.lower()]
                if currency == 'USD':
                    return '${:.2f}'.format(price)
                elif currency == 'EUR':
                    return '{:.2f}€'.format(price * 0.85)
                elif currency == 'GBP':
                    return '£{:.2f}'.format(price * 0.73)
                else:
                    return 'Invalid currency.'
            else:
                # suggest similar fruit names
                suggestions = []
                for name in prices:
                    if name.startswith(fruit.lower()):
                        suggestions.append(name.capitalize())
                if suggestions:
                    return 'Fruit not found. Did you mean: ' + ', '.join(suggestions) + '?'
                else:
                    return 'Fruit not found.'
    except FileNotFoundError:
        return 'Error: file not found.'
```
