    static void Main(string[] args) {
        // Define variables
        double avgTicketPrice = 50.0; // Average ticket price
        int numPerformances = 20; // Number of performances
        int seatingCapacity = 1000; // Seating capacity
        double inflationRate = 0.02; // Annual inflation rate
        double ticketPriceChangeRate = 0.05; // Annual ticket price change rate
        double seatingCapacityChangeRate = -0.01; // Annual seating capacity change rate
        // Calculate total revenue
        double totalRevenue = 0.0;
        double ticketPrice = avgTicketPrice;
        int seating = seatingCapacity;
