            ticketPrice *= (1 + ticketPriceChangeRate);
            seating = (int)(seating * (1 + seatingCapacityChangeRate));
            // Calculate revenue for this performance
            double revenue = ticketPrice * seating;
            // Adjust revenue for inflation
            revenue /= Math.Pow(1 + inflationRate, i);
            // Add revenue to total
            totalRevenue += revenue;
        }
        // Print total revenue
        Console.WriteLine("Total revenue generated by Carmen: $" + totalRevenue.ToString("N2"));
    }
}
