Here is a sample code that can extract the necessary information from a dataset and format it into a JSON list. This code uses the RapidJSON library for parsing and formatting JSON data.
```c++
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"
using namespace rapidjson;
// Define a struct to hold the UN member data
struct UNMember {
    std::string official_name;
    std::string short_name;
    std::string region;
};
int main() {
    // Load the dataset from a file
    std::ifstream ifs("un_members.json");
    std::string json_str((std::istreambuf_iterator<char>(ifs)), (std::istreambuf_iterator<char>()));
    // Parse the JSON data
    Document doc;
    doc.Parse(json_str.c_str());
    // Create a map to store the UN member data
    std::unordered_map<std::string, UNMember> un_members;
    // Loop through the JSON data and extract the necessary information
    for (Value::ConstValueIterator itr = doc.Begin(); itr != doc.End(); ++itr) {
        if (!itr->HasMember("name") || !itr->HasMember("alpha-2") || !itr->HasMember("region")) {
            continue;
        }
        std::string name = (*itr)["name"].GetString();
        std::string short_name = (*itr)["alpha-2"].GetString();
        std::string region = (*itr)["region"].GetString();
        // Correct any errors in the data
        if (name == "Côte d'Ivoire") {
            name = "Cote d'Ivoire";
        }
        else if (name == "Korea, Democratic People's Republic of") {
            name = "North Korea";
        }
        else if (name == "Korea, Republic of") {
            name = "South Korea";
        }
        else if (name == "Moldova, Republic of") {
            name = "Moldova";
        }
        else if (name == "Russian Federation") {
            short_name = "RU";
        }
        else if (name == "Taiwan, Province of China") {
            name = "Taiwan";
            short_name = "TW";
        }
        else if (name == "United Kingdom of Great Britain and Northern Ireland") {
            name = "United Kingdom";
        }
        else if (name == "United States of America") {
            name = "United States";
        }
        if (region == "Africa") {
            region = "AF";
        }
        else if (region == "Americas") {
            region = "AM";
        }
        else if (region == "Asia") {
            region = "AS";
        }
        else if (region == "Europe") {
            region = "EU";
        }
        else if (region == "Oceania") {
            region = "OC";
        }
        // Add the UN member data to the map
        UNMember member = { name, short_name, region };
        un_members[name] = member;
    }
    // Format the UN member data as a JSON list
    StringBuffer sb;
    Writer<StringBuffer> writer(sb);
    writer.StartArray();
    for (auto const& [name, member] : un_members) {
        writer.StartObject();
        writer.Key("official_name");
        writer.String(member.official_name.c_str());
        writer.Key("short_name");
        writer.String(member.short_name.c_str());
        writer.Key("region");
        writer.String(member.region.c_str());
        writer.EndObject();
    }
    writer.EndArray();
    // Print the JSON list
    std::cout << sb.GetString() << std::endl;
    return 0;
}
```
This code loads the UN member data from a JSON file and parses it using the RapidJSON library. It then loops through the JSON data, extracts the necessary information, and corrects any errors in the data. Finally, it formats the UN member data as a JSON list and prints it to the console.
Note that this code assumes that the UN member data is stored in a JSON file named "un_members.json" and that the RapidJSON library is installed on the system. You may need to modify the code to fit your specific needs.

